label_replace(
  label_replace(
    label_join(
  label_join(
  sum_over_time(
                    sum by (route, status, method, host, mode, source_service, source_namespace) (
                      clamp_min(
                        nginx_http_requests_total{namespace="$namespace", route=~"$route", route!~"/metrics|", status=~"${status:pipe}", host=~"$host"}
                        - on(route, status, method, host, mode, source_service, source_namespace, pod)
                        (nginx_http_requests_total{namespace="$namespace", route=~"$route", route!~"/metrics|", status=~"${status:pipe}", host=~"$host"} offset 15s)
                      , 0)
                    )[30s:15s]
                  ) > 0
                  and (avg(nginx_http_request_duration_seconds{namespace="$namespace", route=~"$route", route!~"/metrics|", status=~"${status:pipe}", host=~"$host"}) by (route, status, method, host, mode, source_service, source_namespace) > 0),
  "statusroutemethodhost", ":", "status", "route", "method", "host"
),
  "statusroutemethodhostsource_servicesource_namespace", ":", "statusroutemethod", "source_service", "source_namespace"
)> 0,
    "mode", "in", "mode", "0"
  ),
  "mode", "out", "mode", "1"
)

